# I will proceed with the task as described in the 'task' key of the context.

task_description = context["task"]
print(f"Task description: {task_description}")

# Generate the list of fruits using llm_query, ensuring the constraints are met.
# I will ask the sub-LLM to directly return the structured output.
fruit_list_response = await llm_query(
    {"task": task_description + " Return the list in the specified JSON schema.",
     "schema_description": "The output should be a JSON object with a single key 'fruits', which is an array of strings (fruit names)."},
    schema=fruits_schema
)

print(f"Generated fruit list: {fruit_list_response}")

# Validate the generated list against the length constraint (at least two fruits with 8+ characters)
long_fruits_count = sum(1 for fruit in fruit_list_response["fruits"] if len(fruit) >= 8)

if long_fruits_count < 2:
    print("The generated list does not meet the requirement of having at least two fruits with 8 or more characters. Regenerating...")
